let lastNote = '';
export function residentNote(name) {
  const pool = (NOTES[lang] || NOTES.en)[name] || NOTES.en.Otto;
  let n = pool[Math.floor(Math.random() * pool.length)];
  if (n === lastNote && pool.length > 1) n = pool[(pool.indexOf(n) + 1) % pool.length];
  lastNote = n;
  return n;
}
